/**
 * PayoffAnalysisTab.jsx
 * Payoff diagram visualization and profit/loss analysis
 */

import React, { useState } from 'react';
import { BarChart3, Settings } from 'lucide-react';
import { useOptionPricing } from '../../../hooks/useOptionPricing';
import PayoffChart from '../../PayoffChart';

const PayoffAnalysisTab = () => {
  const {
    parameters,
    updateParameter,
    results,
    validation,
    calculateOptionPrice
  } = useOptionPricing();

  const [chartConfig, setChartConfig] = useState({
    priceRange: 20, // Price range percentage around current price
    showPayoff: true
  });

  const [isPayoffChartExpanded, setIsPayoffChartExpanded] = useState(false);

  // Calculate price range for charts
  const getPriceRange = () => {
    const centerPrice = parameters.S;
    const range = (centerPrice * chartConfig.priceRange) / 100;
    return {
      min: Math.max(0, centerPrice - range),
      max: centerPrice + range
    };
  };

  const priceRange = getPriceRange();

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3 mb-6">
        <BarChart3 className="w-6 h-6 text-red-600" />
        <h2 className="text-2xl font-semibold">Payoff Analysis</h2>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Configuration Panel */}
        <div className="space-y-4">
          <h3 className="text-lg font-semibold mb-4">Analysis Parameters</h3>

          {/* Market Parameters */}
          <div>
            <label className="block text-sm font-medium mb-2">Underlying Price</label>
            <input
              type="number"
              value={parameters.S}
              onChange={(e) => updateParameter('S', parseFloat(e.target.value) || 0)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="100"
              step="0.01"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Strike Price</label>
            <input
              type="number"
              value={parameters.K}
              onChange={(e) => updateParameter('K', parseFloat(e.target.value) || 0)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="100"
              step="0.01"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Time to Expiry (Years)</label>
            <input
              type="number"
              value={parameters.T}
              onChange={(e) => updateParameter('T', parseFloat(e.target.value) || 0)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="0.25"
              step="0.01"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Volatility (%)</label>
            <input
              type="number"
              value={parameters.sigma * 100}
              onChange={(e) => updateParameter('sigma', (parseFloat(e.target.value) || 0) / 100)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="20"
              step="0.01"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Risk-Free Rate (%)</label>
            <input
              type="number"
              value={parameters.r * 100}
              onChange={(e) => updateParameter('r', (parseFloat(e.target.value) || 0) / 100)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="5"
              step="0.01"
            />
          </div>

          {/* Chart Configuration */}
          <hr className="my-4" />

          <div>
            <label className="block text-sm font-medium mb-2">Price Range (%)</label>
            <input
              type="number"
              value={chartConfig.priceRange}
              onChange={(e) => setChartConfig(prev => ({ ...prev, priceRange: parseFloat(e.target.value) || 20 }))}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="20"
              step="5"
              min="5"
              max="50"
            />
            <p className="text-xs text-gray-500 mt-1">
              Range: ${priceRange.min.toFixed(2)} - ${priceRange.max.toFixed(2)}
            </p>
          </div>
        </div>

        {/* Charts Section */}
        <div className="lg:col-span-3 flex flex-col">
          {/* Payoff Diagram */}
          <div className="bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 p-6 relative overflow-hidden flex-1 min-h-[500px]">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold">Payoff Diagram</h3>
              <button
                onClick={() => setIsPayoffChartExpanded(!isPayoffChartExpanded)}
                className="flex items-center gap-1 text-red-600 hover:text-red-700"
              >
                <Settings className="w-4 h-4" />
                {isPayoffChartExpanded ? 'Collapse' : 'Expand'}
              </button>
            </div>

            {validation.isValid ? (
              <div className={`relative transition-all duration-300 ${isPayoffChartExpanded ? 'h-[calc(100vh-400px)]' : 'h-[calc(100%-60px)]'} w-full overflow-visible`}>
                <PayoffChart
                  parameters={parameters}
                  results={results}
                  priceRange={priceRange}
                  calculateOptionPrice={calculateOptionPrice}
                />
              </div>
            ) : (
              <div className="h-96 flex items-center justify-center bg-gray-50 dark:bg-gray-700 rounded">
                <p className="text-gray-500 dark:text-gray-400">Configure parameters to view payoff diagram</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PayoffAnalysisTab;
