/**
 * PayoffChart.jsx
 * Interactive payoff diagram showing profit/loss for option strategies
 */

import React, { useState } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine } from 'recharts';

const PayoffChart = ({ parameters, strangleSpread, calculateOptionPrice }) => {
  const [selectedStrategies, setSelectedStrategies] = useState(['call', 'put']);

  if (!parameters) return null;

  // Generate stock price range for payoff calculation
  const stockPriceRange = [];
  const minPrice = Math.max(parameters.S * 0.6, 10);
  const maxPrice = parameters.S * 1.4;
  const step = (maxPrice - minPrice) / 100;

  for (let price = minPrice; price <= maxPrice; price += step) {
    stockPriceRange.push(price);
  }

  // Calculate payoffs for each strategy at expiration (T=0)
  const payoffData = stockPriceRange.map(stockPrice => {
    const data = {
      stockPrice: stockPrice,
      breakeven: 0
    };

    // Call option payoff (long call)
    const callPayoff = Math.max(stockPrice - parameters.K, 0) - parameters.K * 0.05; // Simplified premium
    const actualCallPrice = calculateOptionPrice(parameters.S, parameters.K, parameters.T, parameters.r, parameters.sigma, parameters.q, 'call');
    data.call = Math.max(stockPrice - parameters.K, 0) - actualCallPrice;

    // Put option payoff (long put)
    const actualPutPrice = calculateOptionPrice(parameters.S, parameters.K, parameters.T, parameters.r, parameters.sigma, parameters.q, 'put');
    data.put = Math.max(parameters.K - stockPrice, 0) - actualPutPrice;

    // Straddle payoff (long call + long put at same strike)
    data.straddle = data.call + data.put;

    // Strangle payoff (long OTM call + long OTM put)
    const strangleCallStrike = parameters.K + strangleSpread;
    const stranglePutStrike = parameters.K - strangleSpread;
    const strangleCallPrice = calculateOptionPrice(parameters.S, strangleCallStrike, parameters.T, parameters.r, parameters.sigma, parameters.q, 'call');
    const stranglePutPrice = calculateOptionPrice(parameters.S, stranglePutStrike, parameters.T, parameters.r, parameters.sigma, parameters.q, 'put');

    const strangleCallPayoff = Math.max(stockPrice - strangleCallStrike, 0) - strangleCallPrice;
    const stranglePutPayoff = Math.max(stranglePutStrike - stockPrice, 0) - stranglePutPrice;
    data.strangle = strangleCallPayoff + stranglePutPayoff;

    return data;
  });

  const strategies = [
    { key: 'call', label: 'Call Option', color: '#10b981', description: `Long ${parameters.K} Call` },
    { key: 'put', label: 'Put Option', color: '#ef4444', description: `Long ${parameters.K} Put` },
    { key: 'straddle', label: 'Straddle', color: '#f59e0b', description: `Long ${parameters.K} Straddle` },
    { key: 'strangle', label: 'Strangle', color: '#8b5cf6', description: `Long ${parameters.K - (strangleSpread || 0)}/${parameters.K + (strangleSpread || 0)} Strangle` }
  ];

  const toggleStrategy = (strategyKey) => {
    setSelectedStrategies(prev =>
      prev.includes(strategyKey)
        ? prev.filter(s => s !== strategyKey)
        : [...prev, strategyKey]
    );
  };

  const formatTooltip = (value, name, props) => {
    if (name === 'stockPrice') return null;
    const strategy = strategies.find(s => s.key === name);
    return [
      `$${value.toFixed(2)}`,
      strategy ? strategy.label : name
    ];
  };

  const formatXAxisLabel = (value) => `$${value.toFixed(0)}`;
  const formatYAxisLabel = (value) => `$${value.toFixed(0)}`;

  return (
    <div className="space-y-4">
      {/* Strategy Selection */}
      <div className="border border-gray-200 dark:border-gray-700 rounded p-3">
        <label className="text-xs font-medium text-gray-700 dark:text-gray-300 mb-2 block">
          Strategies to Display
        </label>
        <div className="flex flex-wrap gap-2">
          {strategies.map(strategy => (
            <button
              key={strategy.key}
              onClick={() => toggleStrategy(strategy.key)}
              className={`px-3 py-1 rounded text-xs transition-colors border ${
                selectedStrategies.includes(strategy.key)
                  ? 'bg-blue-100 text-blue-800 border-blue-300 dark:bg-blue-900/20 dark:text-blue-200 dark:border-blue-700'
                  : 'bg-gray-100 text-gray-600 border-gray-300 dark:bg-gray-700 dark:text-gray-400 dark:border-gray-600'
              }`}
            >
              <div className="flex items-center space-x-2">
                <div
                  className="w-3 h-3 rounded-full"
                  style={{ backgroundColor: strategy.color }}
                ></div>
                <span>{strategy.label}</span>
              </div>
            </button>
          ))}
        </div>

        {/* Strategy Descriptions */}
        <div className="mt-2 text-xs text-gray-500 dark:text-gray-400">
          {selectedStrategies.map(strategyKey => {
            const strategy = strategies.find(s => s.key === strategyKey);
            return strategy ? (
              <div key={strategyKey} className="flex items-center space-x-2">
                <div
                  className="w-2 h-2 rounded-full"
                  style={{ backgroundColor: strategy.color }}
                ></div>
                <span>{strategy.description}</span>
              </div>
            ) : null;
          })}
        </div>
      </div>

      {/* Chart */}
      <div className="h-96 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={payoffData} margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
            <CartesianGrid strokeDasharray="3 3" className="opacity-30" />
            <XAxis
              dataKey="stockPrice"
              tickFormatter={formatXAxisLabel}
              type="number"
              scale="linear"
              domain={['dataMin', 'dataMax']}
              label={{ value: 'Stock Price at Expiration', position: 'insideBottom', offset: -10 }}
            />
            <YAxis
              tickFormatter={formatYAxisLabel}
              label={{ value: 'Profit / Loss', angle: -90, position: 'insideLeft' }}
            />
            <Tooltip
              formatter={formatTooltip}
              labelFormatter={(value) => `Stock Price: $${value.toFixed(2)}`}
              contentStyle={{
                backgroundColor: 'rgba(255, 255, 255, 0.95)',
                border: '1px solid #e5e7eb',
                borderRadius: '6px',
                boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)'
              }}
            />
            <Legend
              wrapperStyle={{ paddingTop: 20 }}
              content={({ payload }) => (
                <div className="flex flex-wrap gap-2">
                  {payload.map(entry => {
                    const strategy = strategies.find(s => s.key === entry.dataKey);
                    return strategy && selectedStrategies.includes(strategy.key) ? (
                      <div key={entry.dataKey} className="flex items-center">
                        <div
                          className="w-3 h-3 rounded-full mr-1"
                          style={{ backgroundColor: strategy.color }}
                        ></div>
                        <span className="text-xs text-gray-700 dark:text-gray-300">{strategy.label}</span>
                      </div>
                    ) : null;
                  })}
                </div>
              )}
            />

            {/* Breakeven line at zero */}
            <ReferenceLine y={0} stroke="#000000" strokeWidth={3} />

            {/* Strike price line */}
            <ReferenceLine
              x={parameters.K}
              stroke="#ffffff"
              strokeDasharray="4 4"
              strokeWidth={3}
            />

            {selectedStrategies.includes('call') && (
              <Line type="monotone" dataKey="call" stroke="#10b981" strokeWidth={2} dot={false} />
            )}
            {selectedStrategies.includes('put') && (
              <Line type="monotone" dataKey="put" stroke="#ef4444" strokeWidth={2} dot={false} />
            )}
            {selectedStrategies.includes('straddle') && (
              <Line type="monotone" dataKey="straddle" stroke="#f59e0b" strokeWidth={2} dot={false} />
            )}
            {selectedStrategies.includes('strangle') && (
              <Line type="monotone" dataKey="strangle" stroke="#8b5cf6" strokeWidth={2} dot={false} />
            )}
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default PayoffChart;
